const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    maxSendsPerRun: demoMode ? 6 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const M = {};
M.parseAiJson = (function () {
  const module = { exports: {} };
/**
 * parseAiJson.js – turns raw AI output into JSON. Never throws.
 * Accepts: plain JSON, JSON in ```json fences, JSON surrounded by text.
 */
function findBalanced(text, open, close) {
  const start = text.indexOf(open);
  if (start < 0) return null;
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === open) depth++;
    else if (ch === close) {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  return null;
}

function parseAiJson(text) {
  if (text === null || text === undefined) return { ok: false, error: 'empty AI output' };
  if (typeof text === 'object') return { ok: true, data: text };
  const raw = String(text).trim();
  if (!raw) return { ok: false, error: 'empty AI output' };
  const candidates = [raw];
  const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) candidates.push(fence[1].trim());
  const obj = findBalanced(raw, '{', '}');
  const arr = findBalanced(raw, '[', ']');
  // Prefer whichever structure starts first in the text.
  const oi = raw.indexOf('{');
  const ai = raw.indexOf('[');
  if (obj && arr) candidates.push(...(ai >= 0 && ai < oi ? [arr, obj] : [obj, arr]));
  else if (obj) candidates.push(obj);
  else if (arr) candidates.push(arr);
  for (const c of candidates) {
    try {
      return { ok: true, data: JSON.parse(c) };
    } catch (e) {
      /* try next */
    }
  }
  return { ok: false, error: 'AI output is not valid JSON: ' + raw.slice(0, 120) };
}

/** Pull the text out of an OpenAI or Anthropic response body. */
function extractAiText(response, provider) {
  if (!response || typeof response !== 'object') return '';
  if (provider === 'anthropic' || Array.isArray(response.content)) {
    return (response.content || [])
      .filter((c) => c && c.type === 'text')
      .map((c) => c.text)
      .join('');
  }
  const ch = response.choices && response.choices[0];
  return (ch && ch.message && ch.message.content) || '';
}

function extractUsage(response) {
  const u = (response && response.usage) || {};
  return {
    input: u.prompt_tokens || u.input_tokens || 0,
    output: u.completion_tokens || u.output_tokens || 0,
  };
}

const parseAiApi = { parseAiJson, extractAiText, extractUsage };
if (typeof module !== 'undefined' && module.exports) module.exports = parseAiApi;

  return module.exports;
})();

M.validators = (function () {
  const module = { exports: {} };
/**
 * validators.js – validates the JSON returned by each AI prompt (one validator per prompt id).
 * Used by the shared AI sub-workflow (14_ai_call): invalid output is retried once.
 * Depends on validateEmails.js (passed in as `ve` so the module also works inside n8n).
 */
const REPLY_CATEGORIES = ['Interested', 'Question', 'Referral', 'Later', 'Not interested', 'Unsubscribe', 'Out of office', 'Unclear'];

function isNonEmptyString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

function isIsoDateOrNull(v) {
  return v === null || v === undefined || v === '' || /^\d{4}-\d{2}-\d{2}/.test(String(v));
}

function validateClassification(d) {
  const errors = [];
  if (!d || typeof d !== 'object') return ['not an object'];
  if (!REPLY_CATEGORIES.includes(d.category)) errors.push('category must be one of ' + REPLY_CATEGORIES.join(', '));
  const c = Number(d.confidence);
  if (!Number.isFinite(c) || c < 0 || c > 1) errors.push('confidence must be a number 0..1');
  if (!isIsoDateOrNull(d.return_date)) errors.push('return_date must be YYYY-MM-DD or null');
  if (!isNonEmptyString(d.summary)) errors.push('summary missing');
  ['referral_name', 'referral_email'].forEach((k) => { if (d[k] !== undefined && d[k] !== null && typeof d[k] !== 'string') errors.push(k + ' must be text'); });
  return errors;
}

/**
 * Quality check answers concrete questions with quoted evidence; the score is computed here, not by the model
 * (live test: the model's own 0–100 score for the same sequence varied 70–85 between runs).
 *   opening_specific (bool) 35 · no invented_claims 35 (any invented claim = 0) ·
 *   emails_with_company_detail (steps) 5 each, max 20 · no filler_phrases 10
 */
const GENERIC_DETAIL_WORDS = ['berlin', 'reinigung', 'reinigungsfirma', 'reinigungsunternehmen', 'gebäudereinigung', 'unternehmen', 'firma', 'dienstleistungen',
  'leistungen', 'kunden', 'professionelle', 'umfassende', 'zuverlässige', 'qualität', 'service', 'services'];

function words(t) {
  return String(t || '').toLowerCase().replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/).filter(Boolean);
}

/** First sentence of email 1 after the salutation, from the "E-Mail 1 … Betreff … body" text the checker saw. */
function openingSentence(sequenceText) {
  const m = String(sequenceText || '').match(/E-Mail 1\s*\n(?:Betreff:[^\n]*\n)?([\s\S]*?)(?:\n\s*E-Mail 2|$)/);
  const body = (m ? m[1] : '').replace(/^\s*(Guten Tag|Sehr geehrte[rs]?|Hallo|Liebe[rs]?)[^\n,]*,?\s*/i, '').trim();
  return (body.match(/^[\s\S]*?[.?!–](\s|$)/) || [body])[0];
}

/**
 * The opening counts as specific only if the quoted detail (opening_detail) really appears in the company
 * description AND in the first sentence, and contains at least one distinctive word (not "Berlin", "Reinigung"…).
 * Live negative control: the model said "Unternehmen wie Ihres profitieren…" was specific – this check says no.
 */
function verifiedOpening(d, ctx) {
  if (d.opening_specific !== true) return false;
  if (!ctx) return true;
  const detail = words(d.opening_detail);
  if (!detail.length) return false;
  const summary = ' ' + words(ctx.summary).join(' ') + ' ';
  const opening = ' ' + words(openingSentence(ctx.sequence)).join(' ') + ' ';
  // the campaign's own industry and city are never a distinctive detail ("Sie sind Steuerberater in Hamburg")
  const campaignWords = words((ctx.generic || []).join(' '));
  const stem = (x) => x.slice(0, 8); // "steuerberater" ~ "steuerberatung", "reinigungsunternehmen" ~ "reinigungsfirma"
  const isGeneric = (w) => GENERIC_DETAIL_WORDS.includes(w) || campaignWords.some((g) => g.length >= 4 && (w === g || stem(w) === stem(g)));
  const distinctive = detail.filter((w) => w.length >= 5 && !isGeneric(w));
  return distinctive.length > 0 && distinctive.every((w) => summary.includes(' ' + w + ' ') || summary.includes(w)) &&
    distinctive.some((w) => opening.includes(w));
}

/**
 * Quality check answers concrete questions with quoted evidence; the score is computed here, not by the model
 * (live test: the model's own 0–100 score for the same sequence varied 70–85 between runs).
 *   verified specific opening 35 · no invented_claims 35 (any invented claim = 0) ·
 *   emails_with_company_detail (steps) 5 each, max 20 · no filler_phrases 10
 * ctx (optional): {summary, sequence} to verify the opening quote.
 */
function qualityScore(d, ctx) {
  if (!d || typeof d !== 'object') return 0;
  const steps = Array.isArray(d.emails_with_company_detail) ? new Set(d.emails_with_company_detail.map(Number).filter((n) => n >= 1 && n <= 4)).size : 0;
  // fail-safe: a missing answer earns nothing (an absent list is not "no invented claims")
  return (verifiedOpening(d, ctx) ? 35 : 0) +
    (Array.isArray(d.invented_claims) && d.invented_claims.length === 0 ? 35 : 0) +
    Math.min(20, steps * 5) +
    (Array.isArray(d.filler_phrases) && d.filler_phrases.length === 0 ? 10 : 0);
}

function validateQuality(d) {
  const errors = [];
  if (!d || typeof d !== 'object') return ['not an object'];
  if (typeof d.opening_specific !== 'boolean') errors.push('opening_specific must be true/false');
  ['invented_claims', 'filler_phrases', 'emails_with_company_detail'].forEach((k) => { if (!Array.isArray(d[k])) errors.push(k + ' must be an array'); });
  if (d.issues !== undefined && !Array.isArray(d.issues)) errors.push('issues must be an array');
  return errors;
}

function validateSummary(d) {
  if (!d || !isNonEmptyString(d.summary)) return ['summary missing'];
  const errors = d.summary.length > 600 ? ['summary too long'] : [];
  // contacts and trigger are optional (older answers without them stay valid); their content is verified in contacts.js
  if (d.contacts !== undefined && !Array.isArray(d.contacts)) errors.push('contacts must be a list');
  if (d.trigger !== undefined && d.trigger !== null && typeof d.trigger !== 'string') errors.push('trigger must be text');
  return errors;
}

function validateImpressumFallback(d) {
  if (!d || typeof d !== 'object') return ['not an object'];
  const errors = [];
  ['contact_name', 'contact_role', 'email'].forEach((k) => {
    if (d[k] !== null && d[k] !== undefined && typeof d[k] !== 'string') errors.push(k + ' must be string or null');
  });
  return errors;
}

function validateBrief(d) {
  const errors = [];
  if (!d || typeof d !== 'object') return ['not an object'];
  if (!['hot', 'warm', 'cold'].includes(String(d.temperature || '').toLowerCase())) errors.push('temperature must be hot, warm or cold');
  if (!isNonEmptyString(d.brief)) errors.push('brief missing');
  return errors;
}

function validateWeekly(d) {
  if (!d || !isNonEmptyString(d.summary)) return ['summary missing'];
  const lines = d.summary.split('\n').filter((l) => l.trim());
  return lines.length > 7 ? ['summary must be about 5 lines'] : [];
}

function validateInterestedReply(d, opts, ve) {
  const errors = [];
  if (!d || typeof d !== 'object') return ['not an object'];
  if (!isNonEmptyString(d.body)) return ['body missing'];
  if (opts && opts.calendlyLink && !d.body.includes(opts.calendlyLink)) errors.push('calendly link missing');
  if (ve && ve.hasInformal(d.body)) errors.push('informal "du" form');
  if (ve && ve.hasPlaceholder(d.body)) errors.push('leftover placeholder');
  return errors;
}

function validateEmailSequence(d, opts, ve) {
  const seq = ve.normaliseSequence(d);
  if (!seq) return ['expected {"emails": [...]}'];
  const errors = ve.validateSequence(seq, { footer: opts && opts.footer, senderName: opts && opts.senderName }).errors;
  const first = (d.emails || []).find((e) => Number(e && e.step) === 1);
  const alt = first && String(first.subject_alt || '').trim();
  if (alt && ve.countWords(alt) > ve.MAX_SUBJECT_WORDS) errors.push(`step 1: subject_alt has ${ve.countWords(alt)} words (max ${ve.MAX_SUBJECT_WORDS})`);
  return errors;
}

function validateReferralIntro(d, opts, ve) {
  if (!d || typeof d !== 'object') return ['not an object'];
  if (!isNonEmptyString(d.body)) return ['body missing'];
  if (!isNonEmptyString(d.subject)) return ['subject missing'];
  return ve ? ve.validateEmail({ step: 1, subject: d.subject, body: d.body }, { senderName: opts && opts.senderName }) : [];
}

function validateMeetingBrief(d) {
  if (!d || typeof d !== 'object') return ['not an object'];
  const errors = [];
  if (!isNonEmptyString(d.about)) errors.push('about missing');
  if (!Array.isArray(d.questions_to_ask) || d.questions_to_ask.length < 1 || d.questions_to_ask.some((q) => !isNonEmptyString(q))) errors.push('questions_to_ask: 1+ questions');
  ['why_now', 'conversation'].forEach((k) => { if (d[k] !== undefined && d[k] !== null && typeof d[k] !== 'string') errors.push(k + ' must be text'); });
  return errors;
}

const VALIDATORS = {
  meeting_brief: validateMeetingBrief,
  referral_intro: validateReferralIntro,
  email_sequence: validateEmailSequence,
  quality_check: validateQuality,
  reply_classifier: validateClassification,
  company_summary: validateSummary,
  impressum_fallback: validateImpressumFallback,
  inbound_lead_brief: validateBrief,
  weekly_report: validateWeekly,
  interested_reply: validateInterestedReply,
};

/** Deterministic clean-up before validation: the same salutation + signature frame on every email we write. */
function prepareByPrompt(promptId, data, opts, ve) {
  if ((promptId === 'interested_reply' || promptId === 'referral_intro') && ve && data && typeof data.body === 'string' && opts && opts.frame) {
    return Object.assign({}, data, { body: ve.ensureFrame(data.body.replace(/\\n/g, '\n'), opts) });
  }
  if (promptId !== 'email_sequence' || !ve || !data || !Array.isArray(data.emails)) return data;
  return Object.assign({}, data, { emails: data.emails.map((e) => Object.assign({}, e, { body: ve.ensureFrame(String(e.body || '').replace(/\\n/g, '\n'), opts || {}) })) });
}

function validateByPrompt(promptId, data, opts, ve) {
  const fn = VALIDATORS[promptId];
  if (!fn) return { ok: false, errors: ['unknown prompt id ' + promptId] };
  const errors = fn(data, opts || {}, ve);
  return { ok: errors.length === 0, errors };
}

const validatorsApi = { REPLY_CATEGORIES, prepareByPrompt, validateByPrompt, VALIDATORS, qualityScore, verifiedOpening, openingSentence };
if (typeof module !== 'undefined' && module.exports) module.exports = validatorsApi;

  return module.exports;
})();

M.validateEmails = (function () {
  const module = { exports: {} };
/**
 * validateEmails.js – checks an AI-written 4-step sequence before it is stored or sent.
 * Rules (PLAN.md Module 4): 4 steps, message text < 90 words (salutation, signature and footer excluded), formal "Sie" only,
 * no placeholders, no exclamation marks, a legal footer on every final email.
 */
const MAX_WORDS = 90; // first email: under 90 words (Nexsale blog: max. 90)
const MAX_FOLLOWUP_WORDS = 50; // follow-ups: max. 50 words, one new angle (Nexsale blog)
const MAX_SUBJECT_WORDS = 5; // subject lines: max. 5 words (Nexsale blog)
const INFORMAL_RE = /\b(du|dich|dir|dein|deine|deinen|deinem|deiner|deines|euch|euer|eure|ihr seid|hast du|kannst du)\b/i;
const PLACEHOLDER_RE = /(\{\{|\}\}|\[(?:name|firma|company|vorname|nachname|placeholder)[^\]]*\]|<<|>>|\bXXX\b|\bTODO\b|lorem ipsum)/i;
const FOOTER_MARKER = 'Antworten Sie mit STOP';
// empty phrases a professional first contact never uses (checked in code; live: "Firmen wie Ihre", "Kernkompetenzen")
const FILLER_RE = /\b(?:Unternehmen|Firmen|Betriebe)\s+wie\s+(?:Ihres|Ihrer|Ihrem|Ihren|Ihre|Ihr|Sie)\b|in Ihrer Branche|zuverlässige[nrs]?\s+Partner|Kernkompetenz|messbare[n]?\s+Ergebnisse|\bumfassende?[nrs]?\b|exzellent|beeindruckend|revolutionär|Synergie|ich hoffe,? es geht Ihnen gut|Win-win/i;

function countWords(text) {
  return String(text || '')
    .trim()
    .split(/\s+/)
    .filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
}

function hasInformal(text) {
  // "Sie"/"Ihnen" are fine. Lowercase "ihr" as pronoun is informal; "Ihr" (capital) is formal possessive.
  if (INFORMAL_RE.test(String(text || ''))) return true;
  return /(^|[.!?]\s+|\s)ihr\s+(habt|seid|könnt|wollt)\b/.test(String(text || ''));
}

function hasPlaceholder(text) {
  return PLACEHOLDER_RE.test(String(text || ''));
}

function stripFooter(body, footer) {
  const b = String(body || '');
  if (footer && b.includes(footer.trim())) return b.slice(0, b.indexOf(footer.trim())).trim();
  const i = b.indexOf('\n-- \n');
  return i >= 0 ? b.slice(0, i).trim() : b.trim();
}

function validateEmail(email, opts) {
  opts = opts || {};
  const errors = [];
  if (!email || typeof email !== 'object') return ['email is not an object'];
  const subject = String(email.subject || '').trim();
  const body = String(email.body || '');
  const core = stripFooter(body, opts.footer);
  const step = email.step;
  if (!subject) errors.push(`step ${step}: subject missing`);
  if (subject.length > 80) errors.push(`step ${step}: subject longer than 80 characters`);
  if (Number(step) === 1 && countWords(subject) > MAX_SUBJECT_WORDS) errors.push(`step 1: subject has ${countWords(subject)} words (max ${MAX_SUBJECT_WORDS})`);
  if (!core) errors.push(`step ${step}: body missing`);
  const words = countWords(messageText(core));
  if (words >= MAX_WORDS) errors.push(`step ${step}: body has ${words} words (max ${MAX_WORDS - 1})`);
  else if (Number(step) > 1 && words > MAX_FOLLOWUP_WORDS) errors.push(`step ${step}: follow-up has ${words} words (max ${MAX_FOLLOWUP_WORDS})`);
  if (hasInformal(subject + ' ' + core)) errors.push(`step ${step}: informal "du" form`);
  if (hasPlaceholder(subject + ' ' + body)) errors.push(`step ${step}: leftover placeholder`);
  if (/!/.test(subject + core)) errors.push(`step ${step}: exclamation mark`);
  const msg = messageText(core);
  const filler = msg.match(FILLER_RE);
  if (filler) errors.push(`step ${step}: filler phrase "${filler[0]}"`);
  // exactly one clear call to action: the last paragraph asks a question
  const lastPara = msg.split(/\n\s*\n/).filter((x) => x.trim()).slice(-1)[0] || '';
  if (msg && !lastPara.includes('?')) errors.push(`step ${step}: no question (call to action) in the last paragraph`);
  // a first email of 40+ words as one block of text is hard to read (live: CLS Clean); short messages may be one paragraph
  if (Number(step) === 1 && countWords(msg) >= 40 && msg.split(/\n\s*\n/).filter((x) => x.trim()).length < 2) errors.push('step 1: one block of text, needs at least 2 paragraphs');
  // greeting and sign-off are required (live: the model once dropped both for one lead)
  if (core && !/^(Guten Tag|Sehr geehrte[rs]?|Hallo|Liebe[rs]?|Dear|Hello)\b/i.test(core)) errors.push(`step ${step}: greeting missing`);
  if (core && !/(Viele Grüße|Beste Grüße|Freundliche Grüße|Mit freundlichen Grüßen|Best regards|Kind regards)\s*,?\s*\n?\s*\S+/i.test(core.slice(-250))) errors.push(`step ${step}: sign-off missing`);
  if (opts.senderName && core && !core.slice(-250).includes(opts.senderName)) errors.push(`step ${step}: sender name missing in sign-off`);
  if (opts.requireFooter) {
    if (!body.includes(FOOTER_MARKER) || (opts.footer && !body.includes(opts.footer.trim()))) {
      errors.push(`step ${step}: legal footer missing`);
    }
  }
  return errors;
}

function validateSequence(emails, opts) {
  opts = opts || {};
  const errors = [];
  if (!Array.isArray(emails)) return { ok: false, errors: ['sequence is not an array'] };
